const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const clock=document.querySelector('.clock');function tick(){clock.textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date())+' IST'}tick();setInterval(tick,1000);const links=[...document.querySelectorAll('.hdr nav a')],sections=[...document.querySelectorAll('main>section[id]')];const navIO=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)links.forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}),{rootMargin:'-40% 0px -55%'});sections.forEach(s=>navIO.observe(s));const revealIO=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');revealIO.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(x=>revealIO.observe(x));const cards=[...document.querySelectorAll('.work-card')],caption=document.querySelector('.work-caption'),count=document.querySelector('.work-count strong');let active=0;const names=['VANDANA TRAVELS — WEB DESIGN','INNOVEXA — STOREFRONT','OUT THERE — EXPERIENCE','DIGITAL SYSTEMS — PRODUCT DESIGN'];function arrange(){cards.forEach((c,i)=>{let d=i-active;c.style.transform=`translateX(${d*22-55}%) translateY(${Math.abs(d)*26+36}px) rotateY(${d*-7}deg) rotate(${d*2}deg)`;c.style.zIndex=10-Math.abs(d);c.style.opacity=d===0?1:Math.max(.18,.7-Math.abs(d)*.23)});count.textContent=String(active+1).padStart(2,'0');caption.textContent=names[active]}arrange();document.querySelector('.work-stage').addEventListener('click',e=>{const c=e.target.closest('.work-card');if(c){active=cards.indexOf(c);arrange()}});document.querySelector('.work-stage').addEventListener('keydown',e=>{if(e.key==='ArrowRight')active=(active+1)%cards.length;if(e.key==='ArrowLeft')active=(active-1+cards.length)%cards.length;arrange()});const can=document.querySelector('#sigCanvas'),cx=can.getContext('2d');function size(){let d=Math.min(devicePixelRatio,2),r=can.getBoundingClientRect();can.width=r.width*d;can.height=r.height*d;cx.setTransform(d,0,0,d,0,0)}function field(t=0){let w=can.clientWidth,h=can.clientHeight;cx.clearRect(0,0,w,h);for(let i=0;i<90;i++){let a=i*.55+t*.00015,r=80+i*4.8,x=w/2+Math.cos(a)*r*1.7,y=h/2+Math.sin(a)*r*.58;cx.beginPath();cx.arc(x,y,1+(i%4),0,7);cx.fillStyle=`hsla(${245+i*.7},85%,65%,${.12+(i%5)*.035})`;cx.fill()}if(!reduce)requestAnimationFrame(field)}size();field();addEventListener('resize',size);if(!reduce)addEventListener('pointermove',e=>{document.querySelector('.collage').style.transform=`translate(${(e.clientX/innerWidth-.5)*10}px,${(e.clientY/innerHeight-.5)*8}px)`},{passive:true});
